const markGithubOutboxDelivered = `-- name: MarkGithubOutboxDelivered :exec
UPDATE github_outbox SET delivered_at = ?1 WHERE id IN (/*SLICE:ids*/?)
`

type MarkGithubOutboxDeliveredParams struct {
	DeliveredAt *int64   `json:"deliveredAt"`
	Ids         []string `json:"ids"`
}

func (q *Queries) MarkGithubOutboxDelivered(ctx context.Context, arg MarkGithubOutboxDeliveredParams) error {
	query := markGithubOutboxDelivered
	var queryParams []interface{}
	queryParams = append(queryParams, arg.DeliveredAt)
	if len(arg.Ids) > 0 {
		for _, v := range arg.Ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(arg.Ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	_, err := q.db.ExecContext(ctx, query, queryParams...)
	return err
}

